def transform(grid):
    g = np.array(grid)
    ps = panels(g)
    if not ps:
        ps = [(0, 0, g.shape[0]-1, g.shape[1]-1)]
    y0, x0, y1, x1 = ps[0]
    P = crop(g, y0, x0, y1, x1)
    bg = background(P)
    H, W = P.shape
    emit(P.copy(), "Take the first panel: it holds the starting state (one shape plus single dots).")
    comps = components(P != bg, diagonal=True)
    shape = max(comps, key=len)
    col = int(P[shape[0]])
    dots = set(c for comp in comps if comp is not shape for c in comp)
    sset = set(shape)
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    tip, d = None, None
    for dy, dx in dirs:
        vals = [y*dy + x*dx for y, x in shape]
        m = max(vals)
        ext = [c for c in shape if c[0]*dy + c[1]*dx == m]
        if len(ext) != 1:
            continue
        t = ext[0]
        if dy != 0:
            refl = set((y, 2*t[1]-x) for y, x in shape)
        else:
            refl = set((2*t[0]-y, x) for y, x in shape)
        if refl == sset:
            tip, d = t, (dy, dx)
            break
    # local coordinates of shape relative to tip
    def perp(dd):
        return (dd[1], -dd[0])
    p = perp(d)
    local = [((y-tip[0])*d[0] + (x-tip[1])*d[1], (y-tip[0])*p[0] + (x-tip[1])*p[1]) for y, x in shape]

    def stamp(canvas, t, dd):
        pp = perp(dd)
        for a, b in local:
            y = t[0] + a*dd[0] + b*pp[0]
            x = t[1] + a*dd[1] + b*pp[1]
            if 0 <= y < H and 0 <= x < W:
                canvas[y, x] = col

    def ahead(t, dd):
        y, x = t[0]+dd[0], t[1]+dd[1]
        while 0 <= y < H and 0 <= x < W:
            if (y, x) in dots:
                return (y, x)
            y += dd[0]; x += dd[1]
        return None

    for _ in range(200):
        nxt = ahead(tip, d)
        nd = d
        if nxt is None:
            best = None
            for cand in [perp(d), (-perp(d)[0], -perp(d)[1])]:
                h = ahead(tip, cand)
                if h is not None:
                    dist = abs(h[0]-tip[0]) + abs(h[1]-tip[1])
                    if best is None or dist < best[0]:
                        best = (dist, h, cand)
            if best is None:
                break
            nxt, nd = best[1], best[2]
        dots.discard(nxt)
        tip, d = nxt, nd
        canvas = np.full((H, W), bg)
        for c in dots:
            canvas[c] = int(P[c])
        stamp(canvas, tip, d)
        emit(canvas.copy(), f"Shape moves to dot {tip}, pointing {d}, and eats it.")
    out = np.full((H, W), bg)
    stamp(out, tip, d)
    emit(out.copy(), "Final state: only the shape at its last position remains.")
    return out
